<script setup lang="ts">
const router = useRouter(); const route = useRoute(); const saving = ref(false); const error = ref(''); const name = ref(String(route.query.name ?? '')); const ingredients = ref<string[]>(['']); const steps = ref<string[]>(['']); const paste = ref(''); const chunks = ref<Array<{ text: string; section: 'ingredients' | 'steps' | 'unresolved' }>>([])
function parse() { chunks.value = paste.value.split(/\r?\n/).map(line => line.replace(/^\s*(?:[-*•]|\d+[.)])\s+/, '').trim()).filter(Boolean).map(text => ({ text, section: 'unresolved' })) }
async function save() { saving.value = true; error.value = ''; try { const recipe = await $fetch<any>('/api/recipes', { method: 'POST', body: { action: 'create', name: name.value, ingredients: ingredients.value.filter(Boolean), steps: steps.value.filter(Boolean) } }); await router.push(`/recipes/${recipe.id}`) } catch (cause: any) { error.value = cause?.data?.message ?? 'Could not save recipe.' } finally { saving.value = false } }
function add(list: string[]) { list.push('') }
function useChunks() { ingredients.value = chunks.value.filter(c => c.section === 'ingredients').map(c => c.text); steps.value = chunks.value.filter(c => c.section === 'steps').map(c => c.text); if (!ingredients.value.length) ingredients.value = ['']; if (!steps.value.length) steps.value = [''] }
</script>
<template><main class="prep-page max-w-3xl"><NuxtLink to="/recipes" class="text-sm text-stone-500">← Recipe book</NuxtLink><h1 class="prep-title mt-4">New recipe</h1><p v-if="error" role="alert" class="mt-3 text-sm text-red-700">{{ error }}</p><label class="mt-6 block text-sm font-semibold">Recipe name<input v-model="name" class="prep-input mt-2" /></label><section class="mt-6 prep-card p-5"><h2 class="text-lg font-semibold">Paste and arrange</h2><textarea v-model="paste" rows="6" class="prep-input mt-3" placeholder="Paste a message from the kitchen"></textarea><button class="prep-secondary mt-3" @click="parse">Split into chunks</button><div v-if="chunks.length" class="mt-4 space-y-2"><div v-for="(chunk, index) in chunks" :key="index" class="flex gap-2"><input v-model="chunk.text" class="prep-input" /><select v-model="chunk.section" class="rounded-xl border border-stone-300 px-2"><option value="unresolved">Unresolved</option><option value="ingredients">Ingredients</option><option value="steps">Steps</option></select></div><button class="prep-secondary mt-2" @click="useChunks">Use arranged chunks</button></div></section><div class="mt-6 grid gap-5 md:grid-cols-2"><section class="prep-card p-5"><h2 class="text-lg font-semibold">Ingredients</h2><div v-for="(_, index) in ingredients" :key="index" class="mt-3"><input v-model="ingredients[index]" class="prep-input" @keydown.enter.prevent="add(ingredients)" /></div><button class="prep-secondary mt-3" @click="add(ingredients)">Add ingredient</button></section><section class="prep-card p-5"><h2 class="text-lg font-semibold">Steps</h2><div v-for="(_, index) in steps" :key="index" class="mt-3"><textarea v-model="steps[index]" rows="2" class="prep-input" @keydown.enter.exact.prevent="add(steps)"></textarea></div><button class="prep-secondary mt-3" @click="add(steps)">Add step</button></section></div><button class="prep-primary mt-6" :disabled="saving || !name.trim()" @click="save">{{ saving ? 'Saving…' : 'Save recipe' }}</button></main></template>
